#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

// Standard binary tree node definition
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class TreeBFSTemplate {
public:
    // Core structural framework for level-by-level processing
    vector<vector<int>> levelOrderTraversal(TreeNode* root) {
        if (root == nullptr) {
            return {};
        }

        vector<vector<int>> resultLevels;
        queue<TreeNode*> nodeQueue;

        // 1. Seed your tracking engine with the root node reference
        nodeQueue.push(root);

        while (!nodeQueue.empty()) {
            // 2. Lock down the exact headcount of the active layer generation
            int levelSize = nodeQueue.size();
            vector<int> currentLevelNodes;

            // 3. Exhaust the active layer generation completely
            for (int i = 0; i < levelSize; ++i) {
                TreeNode* currentNode = nodeQueue.front();
                nodeQueue.pop();

                // Record node values or update structural tracking parameters
                currentLevelNodes.push_back(currentNode->val);

                // 4. Inject child node references safely using explicit null guards
                if (currentNode->left != nullptr) {
                    nodeQueue.push(currentNode->left);
                }
                if (currentNode->right != nullptr) {
                    nodeQueue.push(currentNode->right);
                }
            }

            // Commit the finalized level row to your output structure
            resultLevels.push_back(currentLevelNodes);
        }

        return resultLevels;
    }
};

